def transform(grid):
    h, w = len(grid), len(grid[0])

    # A solid row is the divider; repeat the pattern above it below it.
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and 0 < r < h - 1:
            period = r
            if any(v != row[0] for line in grid[:r] for v in line):
                for y in range(r + 1, h):
                    grid[y] = grid[(y - r - 1) % period][:]
                return grid

    # Likewise, a solid column can divide horizontally repeated patterns.
    for c in range(w):
        if all(grid[y][c] == grid[0][c] for y in range(h)) and 0 < c < w - 1:
            period = c
            if any(grid[y][x] != grid[y][c] for y in range(h) for x in range(c)):
                for x in range(c + 1, w):
                    for y in range(h):
                        grid[y][x] = grid[y][(x - c - 1) % period]
                return grid
    return grid
